test_source:
set mode [lindex $argv 0]
set output [lindex $argv 1]
set helper [lindex $argv 2]
set cores {};set banks {};set locations [dict create]
for {set cluster 0} {$cluster<5} {incr cluster} {
    for {set core 0} {$core<4} {incr core} {
        lappend cores [format {numeric/engine/backend/clusters[%d].cluster/cores[%d]} $cluster $core]
    }
    for {set bank 0} {$bank<8} {incr bank} {
        lappend banks [format {numeric/engine/backend/clusters[%d].cluster/aggregate_memory[%d]} $cluster $bank]
    }
}
proc get_db {object args} {
    global cores banks locations mode
    if {$object eq "insts"} {
        if {[string first tri_oracle_sram_memory_compute [lindex $args 1]]>=0} {return $cores}
        if {[string first TS6N28HPCPSVTA16X128M2F [lindex $args 1]]>=0} {return $banks}
        error UNKNOWN_FILTER
    }
    set core [expr {[lsearch -exact $cores $object]>=0}]
    switch -- [lindex $args 0] {
        .name {
            if {$mode eq "old_hierarchy"} {return [string map {".cluster/" ".unit/cluster/implementation/"} $object]}
            if {$mode eq "duplicate" && $object eq [lindex $cores end]} {return [lindex $cores 0]}
            return $object
        }
        .pins {
            if {$mode eq "bad_interface" && $object eq [lindex $cores 0]} {return [lrepeat 3157 pin]}
            return [lrepeat [expr {$core?3158:268}] pin]
        }
        .base_cell.name {return [expr {$core?"tri_oracle_sram_memory_compute":"TS6N28HPCPSVTA16X128M2F"}]}
        .location {return [dict get $locations $object]}
        .orient {return r0}
        .place_status {return fixed}
        default {error UNKNOWN_PROPERTY}
    }
}
proc place_inst {instance x y orientation fixed} {
    global locations
    if {$orientation ne "r0" || $fixed ne "-fixed" || [dict exists $locations $instance]} {error BAD_PLACEMENT}
    dict set locations $instance [list $x $y]
}
source $helper
if {[catch {tri_oracle_place_staged_frame123_macros $output} detail]} {
    puts stderr $detail
    exit 1
}
if {[dict size $locations]!=60} {error INCOMPLETE_PLACEMENT}
puts FRAME123_HIERARCHY_ACCEPTED_60_MACROS
